'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {studyIndependentStep} = require('../../web/src/en-ro-discontinuity-research.js');

// Generated by Piper + the pinned dictionary, NOT from a user's film.
// Audio and subtitle timestamps have a common fixture-authoritative source.
// The research tool never receives actual media, transcript or dictionary text.
const fixturePath = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.resolve(__dirname, '../generated/en-ro-e2e/fixture.json');
const fixture = JSON.parse(fs.readFileSync(fixturePath, 'utf8'));
const offset = fixture.offsetSeconds;
const rows = fixture.pairs;
assert(Number.isFinite(offset) && offset >= 0, 'synthetic fixture offset missing');
assert(Array.isArray(rows) && rows.length >= 24 && rows.length <= 128,
  'independent synthetic cue metadata unavailable');
for (let index = 0; index < rows.length; index++) {
  const cue = rows[index];
  for (const field of ['audioStart', 'audioEnd', 'subtitleStart', 'subtitleEnd']) {
    assert(Number.isFinite(cue[field]), 'nonfinite authored cue timestamp');
  }
  assert(cue.audioStart >= 0 && cue.audioEnd > cue.audioStart);
  assert(Math.abs(cue.subtitleStart - cue.audioStart - offset) < 0.002);
  assert(Math.abs(cue.subtitleEnd - cue.audioEnd - offset) < 0.002);
  if (index) assert(cue.audioStart >= rows[index - 1].audioEnd,
    'audio fixture source timeline is not chronological');
}

function anchorsFor(makeRef, include = () => true) {
  return rows.map((cue, index) => ({cue, index})).filter(({cue, index}) => include(cue, index))
    .map(({cue, index}) => ({
      cueId: index + 1,
      subtitleTime: cue.subtitleStart,
      referenceTime: makeRef(cue, index),
      // This is only a fixture-authoritative correspondence; no production
      // word-match inference, no implicit trust of raw matcher candidates.
      independentlyVerified: true,
    }));
}

function evaluate(anchors, afterEnd = 0) {
  const durationSeconds = Math.max(...anchors.map(a => a.referenceTime))
    + Math.max(2, afterEnd) + 5;
  return studyIndependentStep({
    provenance: 'independently-verified-cue-pairs',
    durationSeconds,
    formula: {a: 1, b: -offset},
    anchors,
  });
}
const middle = Math.floor(rows.length / 2);
const unedited = anchorsFor(cue => cue.audioStart);
assert.strictEqual(evaluate(unedited).supported, false, 'unedited affine fixture must stay negative');

const added = anchorsFor((cue, i) => cue.audioStart + (i >= middle ? 8 : 0));
const inserted = evaluate(added);
assert.strictEqual(inserted.supported, true, 'authored added scene must expose offset step');
assert(Math.abs(inserted.residualStepSeconds - 8) < 0.05);

// A real deletion needs enough time missing between retained anchors.
// Omit eight entire original cues and remap only the remaining authored cues.
const removedStart = middle - 4;
const removedEnd = middle + 4;
const availableGap = rows[removedEnd].audioStart - rows[removedStart - 1].audioEnd;
const removedSeconds = Math.min(8, availableGap - 0.5);
assert(removedSeconds > 1, 'not enough fixture gap for credible cut control');
const deleted = evaluate(anchorsFor(
  (cue, i) => cue.audioStart - (i >= removedEnd ? removedSeconds : 0),
  (cue, i) => i < removedStart || i >= removedEnd,
));
assert.strictEqual(deleted.supported, true, 'authored deleted section must expose offset step');
assert(Math.abs(deleted.residualStepSeconds + removedSeconds) < 0.05);

const drift = evaluate(anchorsFor(cue => cue.audioStart * 1.006));
assert.strictEqual(drift.supported, false, 'linear drift is not an edition cut');
const oneFalse = evaluate(anchorsFor((cue, i) => cue.audioStart + (i === middle ? 8 : 0)));
assert.strictEqual(oneFalse.supported, false, 'one false lexical match cannot prove an edit');
const twoEdits = evaluate(anchorsFor((cue, i) =>
  cue.audioStart + (i >= middle - 5 && i < middle + 5 ? 8 : 0)));
assert.strictEqual(twoEdits.supported, false, 'two ambiguous edits fail closed');
const noAfter = evaluate(anchorsFor(cue => cue.audioStart, (_, i) => i < middle));
assert.strictEqual(noAfter.supported, false, 'no post-edit anchors means no support');
const reordered = anchorsFor(cue => cue.audioStart);
reordered[middle].referenceTime = reordered[middle - 2].referenceTime - 1;
assert.strictEqual(evaluate(reordered).supported, false, 'reordered matches fail closed');
assert.strictEqual(evaluate(anchorsFor(cue => cue.audioStart)
  .map(a => ({...a, independentlyVerified: false}))).supported, false);

const numericOnly = JSON.stringify([inserted, deleted, drift, oneFalse, twoEdits, noAfter]);
for (const row of rows) {
  assert(!numericOnly.includes(row.phrase), 'research report must exclude synthetic dialogue');
  assert(!numericOnly.includes(row.romanian), 'research report must exclude Romanian subtitle text');
}
console.log(JSON.stringify({
  scope: 'generated-fixture-research-only',
  fixtureCues: rows.length,
  referenceOffsetSeconds: offset,
  insertedStepSeconds: inserted.residualStepSeconds,
  removedStepSeconds: deleted.residualStepSeconds,
  negativeControls: ['affine', 'linear-drift', 'single-false-match', 'multiple-edits',
    'missing-late-evidence', 'reordered-matches', 'no-independent-proof'],
  noRuntimeModification: true,
}, null, 2));
